from pathlib import Path
import json,hashlib,subprocess,sys,zlib,base64
ROOT=Path(r'C:\Users\brand\OneDrive\Documents\dead-street')
def git(*args):return subprocess.check_output(['git',*args],cwd=ROOT,text=True).strip()
def h(b):return hashlib.sha256(b).hexdigest()
if git('rev-parse','HEAD')!='ae8b12cb3136c40f2e2476e215bb33a42b93deeb':raise SystemExit('HEAD changed')
if git('remote','get-url','origin')!='https://github.com/LeadLasso-LL/DEADSTREET.git':raise SystemExit('Origin changed')
if git('diff','--cached','--name-only'):raise SystemExit('Index is not empty; preserving staged work')
for name in ['validation.json','validation_mixed.json','native_review/report.json']:
 d=json.loads((ROOT/'tools/vehicle_fleet'/name).read_text())
 if d['errors']:raise SystemExit('Validation failed '+name)
UPDATES=json.loads(zlib.decompress(base64.b64decode('')))
for f in UPDATES:
 p=ROOT/f['path']
 if h(p.read_bytes().replace(b'\r\n',b'\n'))!=f['old_sha256']:raise SystemExit('Notes changed '+f['path'])
for f in UPDATES:(ROOT/f['path']).write_bytes(f['text'].encode('utf-8'))
subprocess.run([sys.executable,'tools/vehicle_fleet/build_guide.py'],cwd=ROOT,check=True)
installed=json.loads((ROOT/'tools/vehicle_fleet_install_manifest.json').read_text())
allowed=set(installed['source_paths'])
allowed.add('tools/vehicle_fleet/review_native.gd')
for rel in list(allowed):
 if rel.endswith('.gd') and (ROOT/(rel+'.uid')).is_file():allowed.add(rel+'.uid')
for folder in ['assets/art/vehicles/fleet','tools/vehicle_fleet/native_review']:
 for p in (ROOT/folder).rglob('*'):
  if p.is_file() and '__pycache__' not in p.parts and (p.suffix in {'.png','.json'} or p.name=='.gdignore'):allowed.add(p.relative_to(ROOT).as_posix())
for rel in ['docs/vehicle_fleet/Dead_Street_Vehicle_Fleet_Guide.pdf','docs/vehicle_fleet/Fleet_Overview.png']:allowed.add(rel)
paths=sorted(x for x in allowed if (ROOT/x).is_file())
pathspec=ROOT/'tools/vehicle_fleet_stage_paths.txt'
pathspec.write_bytes(b'\0'.join(p.encode('utf-8') for p in paths)+b'\0')
subprocess.run(['git','add','--pathspec-from-file='+str(pathspec),'--pathspec-file-nul'],cwd=ROOT,check=True,stdout=subprocess.DEVNULL)
subprocess.run(['git','diff','--cached','--check'],cwd=ROOT,check=True)
staged=set(git('diff','--cached','--name-only').splitlines())
if not staged or not staged<=allowed:raise SystemExit('Unexpected staged scope '+str(staged-allowed))
report={'staged_files':len(staged),'tree':git('write-tree'),'files':sorted(staged),'native_engine':json.loads((ROOT/'tools/vehicle_fleet/native_review/report.json').read_text())['engine']}
(ROOT/'tools/vehicle_fleet_stage_report.json').write_text(json.dumps(report,indent=2))
print('FLEET_STAGED',len(staged),'tree',report['tree'])
print(git('diff','--cached','--shortstat'))
print('UNRELATED_UNSTAGED',git('diff','--name-only'))
